using System.Security.Claims; using Asp.Versioning; using LostFound.Domain.Entities; using LostFound.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace LostFound.Api.Controllers;
[Authorize,ApiController,ApiVersion(1),Route("api/v{version:apiVersion}/blocks")]public sealed class BlocksController(LostFoundDbContext db):ControllerBase{Guid UserId=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public async Task<ActionResult> List(CancellationToken ct)=>Ok(await db.UserBlocks.AsNoTracking().Where(x=>x.BlockerId==UserId).Select(x=>new{x.BlockedId,x.CreatedAtUtc}).ToListAsync(ct));[HttpPost("{blockedId:guid}")]public async Task<IActionResult> Block(Guid blockedId,CancellationToken ct){if(blockedId==UserId)return BadRequest();if(!await db.Users.AnyAsync(x=>x.Id==blockedId,ct))return NotFound();if(!await db.UserBlocks.AnyAsync(x=>x.BlockerId==UserId&&x.BlockedId==blockedId,ct)){db.UserBlocks.Add(new(){BlockerId=UserId,BlockedId=blockedId});await db.SaveChangesAsync(ct);}return NoContent();}[HttpDelete("{blockedId:guid}")]public async Task<IActionResult> Unblock(Guid blockedId,CancellationToken ct){await db.UserBlocks.Where(x=>x.BlockerId==UserId&&x.BlockedId==blockedId).ExecuteDeleteAsync(ct);return NoContent();}}
